    static String readToken(Path card) throws Exception {
        List<String> lines = Files.readAllLines(card);
        for (String line : lines) {
            String s = line.trim();
            if (s.startsWith("token:")) {
                return s.substring(6).trim();
            }
        }
        return "none";
    }
}
